87	  TransitionState(nextState: AgentLifecycleState): void
88	  {
89	    const previousState = this.m_record.state;
90	
91	    if (previousState === nextState)
92	    {
93	      return;
94	    }
95	
96	    this.m_record.state = nextState;
97	    this.m_context.lifecycle.EmitStatus({
98	      key: this.m_record.key,
99	      state: nextState,
100	      previousState,
101	    });
102	  }
