104	  AttachClient(clientId?: string): void
105	  {
106	    if (clientId !== undefined && clientId.length > 0)
107	    {
108	      this.m_record.clients.add(clientId);
109	    }
110	
111	    this.ClearIdleTimer();
112	
113	    if (
114	      this.m_record.state === AgentLifecycleState.Idle ||
115	      this.m_record.state === AgentLifecycleState.Active
116	    )
117	    {
118	      this.TransitionState(AgentLifecycleState.Active);
