266	
267	    this.ClearIdleTimer();
268	    this.TransitionState(AgentLifecycleState.Stopping);
269	
270	    const piSession = this.m_record.piSession;
271	
272	    if (piSession !== undefined)
273	    {
274	      this.m_record.unsubscribePi?.();
275	      this.m_record.unsubscribePi = undefined;
