292	  private ScheduleIdleOffload(): void
293	  {
294	    if (this.m_record.clients.size > 0)
295	    {
296	      return;
297	    }
298	
299	    if (
300	      this.m_record.state !== AgentLifecycleState.Active &&
301	      this.m_record.state !== AgentLifecycleState.Idle
302	    )
303	    {
304	      return;
305	    }
306	
307	    this.TransitionState(AgentLifecycleState.Idle);
308	    this.ClearIdleTimer();
309	
310	    this.m_record.idleTimer = this.m_context.setTimeoutFn(() =>
311	    {
312	      void this.Offload();
313	    }, this.m_context.idleOffloadSeconds * 1000);
314	  }
315	
316	  private ClearIdleTimer(): void
317	  {
318	    if (this.m_record.idleTimer !== undefined)
319	    {
320	      this.m_context.clearTimeoutFn(this.m_record.idleTimer);
321	      this.m_record.idleTimer = undefined;
322	    }
323	  }
324	
325	  private HandlePiEvent(event: AgentSessionEvent): void
326	  {
327	    this.m_context.lifecycle.EmitAgentEvent({
328	      key: this.m_record.key,
329	      event,
330	    });
331	
332	    if (event.type === "agent_start")
333	    {
334	      this.m_record.activeRunCount += 1;
335	      this.ClearIdleTimer();
336	      return;
337	    }
338	
339	    if (event.type === "agent_end")
340	    {
341	      this.m_record.activeRunCount = Math.max(0, this.m_record.activeRunCount - 1);
342	
343	      if (this.m_record.clients.size === 0)
344	      {
345	        this.ScheduleIdleOffload();
346	      }
347	
348	      return;
349	    }
350	
351	    if (event.type === "tool_execution_start")
352	    {
353	      this.m_record.activeToolCount += 1;
354	      this.ClearIdleTimer();
355	      return;
356	    }
357	
358	    if (event.type === "tool_execution_end")
359	    {
360	      this.m_record.activeToolCount = Math.max(0, this.m_record.activeToolCount - 1);
361	
362	      if (
363	        this.m_record.clients.size === 0 &&
364	        this.m_record.activeRunCount === 0 &&
365	        this.m_record.activeToolCount === 0
366	      )
367	      {
368	        this.ScheduleIdleOffload();
369	      }
370	
371	      return;
372	    }
373	
374	    if (event.type === "message_end" && event.message.role === "assistant")
375	    {
376	      void this.HandleAssistantMessageCompleted();
377	    }
378	  }
379	
380	  private async HandleAssistantMessageCompleted(): Promise<void>
381	  {
382	    if (this.m_record.manifestWritten || this.m_record.firstAssistantCompleted)
383	    {
384	      return;
385	    }
386	
387	    this.m_record.firstAssistantCompleted = true;
388	
389	    try
390	    {
391	      let summary = this.m_record.summaryResult;
392	
393	      if (summary === undefined && this.m_record.summaryPromise !== undefined)
394	      {
395	        try
396	        {
397	          summary = await this.m_record.summaryPromise;
398	        }
399	        catch
400	        {
401	          summary = undefined;
402	        }
403	      }
404	
405	      if (summary === undefined)
406	      {
407	        summary = BuildDeterministicSummary(this.m_record.firstUserMessageText ?? "New chat");
408	      }
409	
410	      this.m_record.summaryResult = summary;
411	
412	      const manifest = await WriteInitialManifest(this.m_context.storagePaths, {
413	        pile: this.m_record.key.pile,
414	        sessionId: this.m_record.key.sessionId,
415	        chatName: summary.chatName,
416	        description: summary.description,
417	        rootDirectory: this.m_record.rootDirectory,
418	        model: this.m_record.model,
419	        extensionVersion: x_defaultExtensionVersion,
420	      });
421	
422	      this.m_record.manifest = manifest;
423	      this.m_record.manifestWritten = true;
424	      this.m_context.lifecycle.EmitManifestUpdated({
425	        key: this.m_record.key,
426	        manifest,
427	      });
428	    }
429	    catch (error)
430	    {
431	      const message = error instanceof Error ? error.message : String(error);
432	      this.m_context.lifecycle.EmitError({
433	        key: this.m_record.key,
434	        code: "manifest_write_failed",
435	        message,
436	        fatal: false,
437	      });
438	    }
439	  }
440	}
