442	export async function LoadProvisionalSession(
443	  storagePaths: StoragePaths,
444	  pile: string,
445	  sessionId: string,
446	): Promise<ProvisionalSession>
447	{
448	  const provisionalPath = ResolveProvisionalFilePath(storagePaths, pile, sessionId);
449	  const raw = await readFile(provisionalPath, "utf8");
450	  const parsed = JSON.parse(raw) as {
451	    rootDirectory: string;
452	    model: ModelReference;
453	  };
454	
455	  return {
456	    rootDirectory: parsed.rootDirectory,
457	    model: parsed.model,
458	  };
459	}
460	
461	export async function ResolveSessionBootstrap(
462	  storagePaths: StoragePaths,
463	  pile: string,
464	  sessionId: string,
465	): Promise<{
466	  rootDirectory: string;
467	  model: ModelReference;
468	  sessionFilePath: string;
469	  manifest?: SessionManifest;
470	  provisional?: ProvisionalSession;
471	}>
472	{
473	  const sessionFilePath = ResolveSessionFilePath(storagePaths, pile, sessionId);
474	
475	  try
476	  {
477	    await access(sessionFilePath);
478	  }
479	  catch
480	  {
481	    throw new Error(`session file not found for ${sessionId}`);
482	  }
483	
484	  const hasManifest = await ManifestExists(storagePaths, pile, sessionId);
485	
486	  if (hasManifest)
487	  {
488	    const manifest = await ReadManifest(storagePaths, pile, sessionId);
489	
490	    return {
491	      rootDirectory: manifest.rootDirectory,
492	      model: manifest.model,
493	      sessionFilePath,
494	      manifest,
495	    };
496	  }
497	
498	  const provisional = await LoadProvisionalSession(storagePaths, pile, sessionId);
499	
500	  return {
501	    rootDirectory: provisional.rootDirectory,
502	    model: provisional.model,
503	    sessionFilePath,
504	    provisional,
505	  };
506	}
507	
508	export function CreateRuntimeRecordFromColdResume(
509	  key: SessionKey,
510	  bootstrap: Awaited<ReturnType<typeof ResolveSessionBootstrap>>,
511	): SessionRuntimeRecord
512	{
513	  return {
514	    key,
515	    state: AgentLifecycleState.Cold,
516	    rootDirectory: bootstrap.rootDirectory,
517	    model: bootstrap.model,
518	    sessionFilePath: bootstrap.sessionFilePath,
519	    clients: new Set<string>(),
520	    manifest: bootstrap.manifest,
521	    provisional: bootstrap.provisional,
522	    manifestWritten: bootstrap.manifest !== undefined,
523	    firstUserMessageSent: bootstrap.manifest !== undefined,
524	    firstAssistantCompleted: bootstrap.manifest !== undefined,
525	    activeRunCount: 0,
526	    activeToolCount: 0,
527	    acceptedMessageIds: new Set<string>(),
528	  };
529	}
