418	      .then(() => operation())
419	      .finally(() =>
420	      {
421	        release();
422	        if (this.m_startupLocks.get(encodedKey) === tail)
423	        {
424	          this.m_startupLocks.delete(encodedKey);
425	        }
426	      });
