21	export class FakePiSession extends EventEmitter implements PiSessionHandle
22	{
23	  readonly sessionId: string;
24	  readonly sessionFile: string | undefined;
25	  messages: AgentSession["messages"] = [];
26	  model: ModelReference | undefined;
27	  private m_isStreaming = false;
28	  private m_disposed = false;
29	  promptCalls: Array<{ text: string; options?: { streamingBehavior?: string } }> = [];
30	  steerCalls: string[] = [];
31	  followUpCalls: string[] = [];
32	  abortCalls = 0;
33	
34	  constructor(sessionId: string, sessionFile?: string, model?: ModelReference)
35	  {
36	    super();
37	    this.sessionId = sessionId;
38	    this.sessionFile = sessionFile;
39	    this.model = model;
40	  }
41	
42	  get isStreaming(): boolean
43	  {
44	    return this.m_isStreaming;
45	  }
46	
47	  setStreaming(value: boolean): void
48	  {
49	    this.m_isStreaming = value;
50	  }
51	
52	  async prompt(text: string, options?: { streamingBehavior?: string }): Promise<void>
53	  {
54	    this.promptCalls.push({ text, options });
55	  }
56	
57	  async steer(text: string): Promise<void>
58	  {
59	    this.steerCalls.push(text);
60	  }
61	
62	  async followUp(text: string): Promise<void>
63	  {
64	    this.followUpCalls.push(text);
65	  }
66	
67	  async setModel(model: ModelReference): Promise<void>
68	  {
69	    this.model = model;
70	  }
71	
72	  async abort(): Promise<void>
73	  {
74	    this.abortCalls += 1;
75	    this.m_isStreaming = false;
76	  }
77	
78	  dispose(): void
79	  {
80	    this.m_disposed = true;
81	    this.removeAllListeners();
82	  }
83	
84	  get disposed(): boolean
85	  {
86	    return this.m_disposed;
87	  }
88	
89	  subscribe(listener: (event: AgentSessionEvent) => void): () => void
90	  {
91	    const handler = (event: AgentSessionEvent) => listener(event);
92	    this.on("event", handler);
93	    return () => this.off("event", handler);
94	  }
95	
96	  Emit(event: AgentSessionEvent): void
97	  {
98	    this.emit("event", event);
99	  }
100	
101	  async EmitAssistantTurn(text = "assistant reply"): Promise<void>
102	  {
103	    this.Emit({ type: "agent_start" });
104	    this.Emit({
105	      type: "message_end",
106	      message: {
107	        role: "assistant",
108	        content: [{ type: "text", text }],
109	      } as AgentSession["messages"][number],
110	    });
111	    this.Emit({
112	      type: "agent_end",
113	      messages: [],
114	      willRetry: false,
115	    });
116	  }
117	}
