119	export function CreateTestModelBundle(
120	  authStorage: AuthStorage = CreateInMemoryAuthStorage(),
121	): SheafModelRegistryBundle
122	{
123	  authStorage.setRuntimeApiKey("openai", "test-key");
124	  const modelRegistry = ModelRegistry.create(authStorage);
125	
126	  return {
127	    authStorage,
128	    modelRegistry,
129	    localProviderState: {
130	      models: [],
131	      fetchError: null,
132	      unavailableReason: "local inference not configured",
133	    },
134	  };
135	}
