137	export function CreateTestConfigWithRoot(repoRoot: string): SheafChatConfig
138	{
139	  const config = BuildTestConfig(repoRoot, {
140	    openAiApiKey: "test-key",
141	    agentIdleOffloadSeconds: 2,
142	  });
143	  mkdirSync(path.join(repoRoot, "projects", "demo"), { recursive: true });
144	  return config;
145	}
146	
147	export function CreateStorage(repoRoot: string)
148	{
149	  return CreateStoragePaths(repoRoot);
150	}
151	
152	export interface FakeTimerController
153	{
154	  setTimeout: typeof setTimeout;
155	  clearTimeout: typeof clearTimeout;
156	  RunDueTimers(): void;
157	}
158	
159	export function WaitForManifestUpdated(
160	  manager: { lifecycle: { On: (event: "manifestUpdated", listener: () => void) => () => void } },
161	): Promise<void>
162	{
163	  return new Promise((resolve) =>
164	  {
165	    const unsubscribe = manager.lifecycle.On("manifestUpdated", () =>
166	    {
167	      unsubscribe();
168	      resolve();
169	    });
170	  });
171	}
172	
173	export function CreateFakeTimers(): FakeTimerController & { Advance(ms: number): void }
174	{
175	  const pending = new Map<NodeJS.Timeout, { callback: () => void; dueAt: number }>();
176	  let now = 0;
177	  let nextId = 1;
178	
179	  const setTimeoutFn = ((callback: () => void, delay?: number) =>
180	  {
181	    const id = nextId++ as unknown as NodeJS.Timeout;
182	    pending.set(id, {
183	      callback,
184	      dueAt: now + (delay ?? 0),
185	    });
186	    return id;
187	  }) as typeof setTimeout;
188	
189	  const clearTimeoutFn = ((id: NodeJS.Timeout) =>
190	  {
191	    pending.delete(id);
192	  }) as typeof clearTimeout;
193	
194	  const controller = {
195	    setTimeout: setTimeoutFn,
196	    clearTimeout: clearTimeoutFn,
197	    RunDueTimers()
198	    {
199	      const due = [...pending.entries()].filter(([, entry]) => entry.dueAt <= now);
200	      for (const [id, entry] of due)
201	      {
202	        pending.delete(id);
203	        entry.callback();
204	      }
205	    },
206	    Advance(ms: number)
207	    {
208	      now += ms;
209	      controller.RunDueTimers();
210	    },
211	  };
212	
213	  return controller;
214	}
